/**
 * Register the TTOken Code issues board: its copy, the agent Sessions it remembers, and the Conversation view tab
 * that reads the Session repository's issues through the forge panel Remote.
 * Generated by ttoken/apply-brand.mjs from ttoken/forge/client/install.ts; edit it there.
 */

import type { Context } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-api-session-controller/client'
import type {} from '@deepseek-ai/dsh-api-workspace-controller/client'
import { createSnapshotStore } from '@deepseek-ai/dsh-client-store'
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-client-ui-workspace/client'
import type {} from '@deepseek-ai/dsh-experimental-client-ui-forge/remote'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import { withAgent, withoutAgent, type AgentSessions } from './agents.ts'
import { IssuesBoard, type AgentRequest, type AgentStart, type IssuesBoardInjected } from './IssuesBoard.tsx'
import { TTOKEN_ISSUES_NS, de, en, es, fr, ja, pt, ru, zh } from './locales.ts'

/** Browser storage key of the agent Sessions the board started. */
const AGENTS_STORAGE = 'ttoken-code.issues.agents'
/** Conversation view id of the board. */
const VIEW_ID = 'ttoken-issues'
/** Suffixes tried in turn when the branch an issue suggests already exists; a generated name follows them. */
const BRANCH_SUFFIXES = ['', '-2', '-3'] as const

/**
 * Install the issues board for the forge panel UI's lifetime.
 * @param ctx - forge panel client context, with the forge panel Remote, Sessions, Workspaces and Workspace navigation.
 * @param openLink - open a URL outside the app.
 */
export function installTtokenIssues(ctx: Context, openLink: (url: string) => void): void {
  ctx.effect(() => ctx.locale.register(TTOKEN_ISSUES_NS, { zh, en, ja, es, fr, de, ru, pt }), 'ttoken issues: dictionaries')
  const t = ctx.locale.bind(TTOKEN_ISSUES_NS)
  const agents = createSnapshotStore<AgentSessions>({}, { persist: { name: AGENTS_STORAGE } })

  /**
   * Ask for a worktree on `names[0]`, trying the next name while the branch exists. A Session that gets no worktree
   * works in the Workspace's checkout, which the composer shows.
   */
  const requestBranch = async (sessionId: SessionId, names: readonly (string | null)[]): Promise<void> => {
    const [name, ...rest] = names
    if (name === undefined) return
    const result = await ctx.remote.forgePanel.requestWorktree(sessionId, null, name)
    if (result.ok) return
    if (result.error.code === 'forgePanel/branch-exists' && rest.length > 0) {
      await requestBranch(sessionId, rest)
      return
    }
    console.warn(`ttoken issues: the new session works in the workspace checkout: ${result.error.message}`)
  }

  const start = async (current: SessionId, request: AgentRequest): Promise<AgentStart> => {
    const workspace = ctx.workspaces.list.getSnapshot().items.find(item => item.sessionIds.includes(current))
    if (workspace === undefined) return { kind: 'failed', message: t('handoff.noWorkspace') }
    const opened: { sessionId?: SessionId } = {}
    try {
      await ctx.uiWorkspace.openWorkspace(workspace.workspaceId, (sessionId) => {
        const binding = ctx.sessions.binding(sessionId)
        const conversation = ctx.get('conversation')
        const draft = { prompt: request.prompt, whenDraftExists: 'replace' } as const
        if (binding === undefined || conversation === undefined
          || conversation.input.requestDraftInitialization(binding, draft) === 'blocked') {
          throw new Error(t('handoff.draftFailed'))
        }
        opened.sessionId = sessionId
      })
    } catch (error) {
      return { kind: 'failed', message: error instanceof Error ? error.message : String(error) }
    }
    const { sessionId } = opened
    if (sessionId === undefined) return { kind: 'superseded' }
    agents.set(withAgent(agents.getSnapshot(), request.repository, request.issue, sessionId))
    const { branch } = request
    const names = branch === null ? [null] : [...BRANCH_SUFFIXES.map(suffix => `${branch}${suffix}`), null]
    await requestBranch(sessionId, names)
    return { kind: 'started', sessionId }
  }

  ctx.slots.inject('conversation.view', () => ctx.slots.register({
    name: 'conversation.view',
    id: VIEW_ID,
    order: 20,
    locale: TTOKEN_ISSUES_NS,
    label: () => t('view'),
    inject: (sessionId: SessionId): IssuesBoardInjected => ({
      hooks: { agents },
      load: signal => ctx.remote.forgePanel.issues(sessionId, signal),
      start: async (request) => {
        try {
          return await start(sessionId, request)
        } catch (error) {
          return { kind: 'failed', message: error instanceof Error ? error.message : String(error) }
        }
      },
      forget: (repository, issue) => { agents.set(withoutAgent(agents.getSnapshot(), repository, issue)) },
      openSession: (id) => { ctx.uiWorkspace.openSession(id) },
      openLink,
    }),
  }, IssuesBoard))
}
